#pragma once
#include "desktop_candidates.hpp"
#include <fstream>
#include <regex>
#include <filesystem>
inline private_input::DesktopCandidates readDesktopLayout(const std::filesystem::path& file){private_input::DesktopCandidates state;try{std::ifstream input(file,std::ios::binary);if(!input)return state;input.seekg(0,std::ios::end);if(input.tellg()>4096)return state;input.seekg(0);std::string value((std::istreambuf_iterator<char>(input)),{});auto integer=[&](const char* key,int fallback){std::regex marker(std::string("\"")+key+"\"\\s*:");if(!std::regex_search(value,marker))return fallback;std::regex pattern(std::string("\"")+key+"\"\\s*:\\s*(-?[0-9]{1,4})\\s*(?=[,}])");std::smatch match;if(!std::regex_search(value,match,pattern))throw std::runtime_error("invalid layout value");return std::stoi(match[1].str());};state.configure(integer("collapsedCount",6),integer("expandedColumns",6),integer("expandedRows",6));}catch(...){return {};}return state;}

#include "DesktopTheme.h"
struct DesktopInputPreferences {private_input::DesktopTheme theme;bool pairSymbols=true,caretInside=true;};
inline DesktopInputPreferences readDesktopInputPreferences(const std::filesystem::path&file){DesktopInputPreferences result;try{std::ifstream input(file,std::ios::binary);input.seekg(0,std::ios::end);if(!input||input.tellg()>4096)return result;input.seekg(0);std::string value((std::istreambuf_iterator<char>(input)),{});auto option=[&](const char*key,const std::vector<std::string>&options){std::smatch match;std::regex expression(std::string("\"")+key+"\"\\s*:\\s*\"([a-z]+)\"");if(!std::regex_search(value,match,expression))return 0;auto it=std::find(options.begin(),options.end(),match[1].str());return it==options.end()?0:int(it-options.begin());};auto flag=[&](const char*key){std::smatch match;return !std::regex_search(value,match,std::regex(std::string("\"")+key+"\"\\s*:\\s*(true|false)"))||match[1].str()=="true";};result.theme.mode=option("themeMode",{"system","light","dark"});result.theme.accent=option("themeAccent",{"rose","amber","violet","graphite"});result.pairSymbols=flag("pairSymbols");result.caretInside=flag("caretInside");}catch(...){}return result;}
